export class ExperimentalHousingApi {
    #iframeMessenger;
    constructor(iframeMessenger) {
        this.#iframeMessenger = iframeMessenger;
    }
    async createFromLine(request) {
        return await this.#iframeMessenger.sendRequest("experimental/housing/create-housing-line", request);
    }
    async listTemplates() {
        return await this.#iframeMessenger.sendRequest("experimental/housing/list-templates");
    }
}
